UPDATE provider_institution SET intake_date = 'April, May', updated_at = NOW() WHERE cricos_provider_code = '00246M';

UPDATE courses SET
    course_description = '<p>A Bachelor of Health Science in Clinical Myotherapy equips you with skills and knowledge in evidence-based assessment, treatment and rehabilitation of musculoskeletal pain and associated conditions. </p><p>This course combines health science with skills in manual therapy, pain management and exercise therapy. Gain supervised experience at our student-led clinics and external placements, where you’ll help people recover from pain or injury and improve their physical function and quality of life.</p><p>Graduate prepared for a fulfilling career in the health, fitness and wellbeing where you can make a meaningful difference to people''s lives. </p><p><strong>Upgrade from the Advanced Diploma into the Bachelor of Health Science (Clinical Myotherapy) in 1 year (full time) with 50% of subjects now available online.</strong> </p><p><a href="https://cdn.intelligencebank.com/au/share/RyzZ/GVMkg/kYo0N/original/myotherapy-course-upgrade-flyer">Find out more</a> about our Diploma and Advanced Diploma upgrade program.</p><p><a href="#">More</a> </p><ul> <li>Learn hands-on treatment methods, including soft tissue techniques, dry needling and joint mobilisation </li> <li>Study the biological and social sciences underpinning the discipline </li> <li>Understand the complexities of how the human body moves </li> <li>Extensive clinical experience </li> <li>Master the art of improving physical function and wellbeing </li> <li>This course has a requirement of 200 points of Work-Integrated Learning plus 210 hours of Clinical Practicum</li> </ul><p> Graduates may apply for membership with Myotherapy Association Australia (MA), which recognises this qualification. </p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = 87990,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p> Before you begin your course application, check you meet all the requirements listed below. </p><p>Year 12 (Australian secondary school certificate) or equivalent </p><p><strong>OR</strong> </p><p>Successful completion of a Vocational qualification (AQF Leve 4), or above </p><p><strong>OR</strong> </p><p>Successful completion of at least 0.5 EFTSL at AQF level 5, 0.25 EFTSL at AQF level 6 or above, or equivalent.</p><p> <strong>OR</strong></p><p>Successful completion of Year 10 or equivalent, and a minimum three years of full time relevant work experience that demonstrates skills and knowledge gained through paid or unpaid employment, formal learning and/or non-formal learning (presented on a current resume with attached cover letter).</p>',
    apply_form = 'https://www.think.edu.au/courses/bachelor-of-health-science-clinical-myotherapy',
    updated_at = NOW()
WHERE cricos_course_code = '084579F';
