UPDATE courses SET
    course_description = '<p><a href="#">More</a> </p><ul> <li>Integrity in the pursuit of knowledge - Employability through industry recognised learning </li> <li>A reflexive, globally focused curriculum </li> <li>Access to a global network of facilities and connections </li> <li>Proactive engagement with industry globally </li> <li>Collaboration, teamwork and partnership </li> <li>Learning flexibility at every point </li> <li>Inter-cultural understanding and respect </li> <li>Intellectual and personal welfare of all staff and students </li> <li>This course has a requirement of 400 hours of work placement.</li> </ul><p> Think Education is a member of the Australian College of Nursing, the peak professional body and leading organisation of the nursing profession. </p><p> Our program is accredited by the Australian Nursing and Midwifery Accreditation Council (ANMAC), so you know it meets the required education standards of the Nursing and Midwifery Board of Australia (NMBA). </p><p> Think Education is a member of the Australian Primary Health Care Nurses Association, the peak body for nurses working in primary health care. </p><p> Think Education is a member of the Congress of Aboriginal and Torres Strait Islander Nurses and Midwifery to encourage diversity. </p><p> Think Education is represented on the Council of Deans of Nursing and Midwifery, as part of our commitment to the highest standards of education. </p><p> This course is provided and delivered by Think: Colleges Pty Ltd.</p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = 19290,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p> Before you begin your course application, check you meet the requirements listed below. </p><p>Year 12 or equivalent</p><p> <strong>OR</strong> </p><p>A completed vocational education qualification at Certificate III or Certificate IV level</p><p> <strong>OR</strong> </p><p>Successful completion of a Vocational qualification (AQF Level 5), or above</p><p> <strong>OR</strong> </p><p>For students wanting to apply as a mature age entry, be 21 years of age or older</p>',
    apply_form = 'https://www.think.edu.au/courses/diploma-of-nursing',
    updated_at = NOW()
WHERE cricos_course_code = '110190G';
